make_b <- function(){d<-read_input("pain_values.csv");m<-read_input("pain_summary.csv");lev<-c("Lower early decile","Upper early decile");d$group<-factor(d$group,levels=lev);m$group<-factor(m$group,levels=lev);set.seed(20261108);ggplot(d,aes(group,future_pain,color=group,fill=group))+geom_violin(aes(weight=weight),quantiles=NULL,alpha=.12,color=NA,width=.8)+geom_jitter(aes(alpha=weight),width=.1,height=0,size=.6)+geom_errorbar(data=m,aes(group,ymin=lower,ymax=upper),inherit.aes=FALSE,width=.12,linewidth=.5,color=CFG$ink)+geom_point(data=m,aes(group,mean),inherit.aes=FALSE,shape=23,size=1.8,fill="white",color=CFG$ink)+scale_color_manual(values=c(CFG$blue,CFG$red))+scale_fill_manual(values=c(CFG$blue,CFG$red))+scale_alpha_continuous(range=c(.12,.55),guide="none")+scale_x_discrete(labels=c("Lower","Higher"))+scale_y_continuous(limits=c(0,20.5),breaks=c(0,5,10,15,20),expand=expansion(mult=c(0,.01)))+annotate("text",x=1.5,y=19.5,label="Difference 7.45",size=mm_pt(CFG$font_pt),family=CFG$family)+labs(title="b  Follow-up pain",x="PPSD group",y="WOMAC pain (0-20)")+base_theme()}
